// D2.1 WP-11b (AWR-04 §15.11.2; ADR-125): the deterministic spherical scatter equals the server's pattern() point by point.
// Reference: apps/web/tests/m19/field_cases.json (generated by tests/perception/test_field_golden.py from python/awr/sim/
// perception/field.py): the profile samples are pattern(256, j = 1, r_min = 2, r_max) given as (r, observer elevation), the
// volume samples are pattern(256, targetOrder * 4 + body, r_min = 1, radius_max_m) as world points around the target.
import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import { describe, expect, it } from 'vitest'
import { halton, PATTERN, patternDir, patternInto, patternRadius } from '@/engine/field'

const FIX = JSON.parse(readFileSync(join(import.meta.dirname, '../m19/field_cases.json'), 'utf8')) as {
  profiles: { kind: string; samples: [number, number, number | null][] }[]
  volumes: { samples: { target: string; body: number; pos: [number, number, number]; cfg: { radius_max_m: number }; points: [number, number, number, number, boolean][] }[] }
}

describe('field pattern (AWR-04 §15.11.2)', () => {
  it('Halton radical inverses', () => {
    expect([1, 2, 3, 4, 5].map((i) => halton(i, 2))).toEqual([0.5, 0.25, 0.75, 0.125, 0.625])
    expect(halton(1, 3)).toBeCloseTo(1 / 3, 15)
    expect(halton(7, 5)).toBeCloseTo(2 / 5 + 1 / 25, 15)
  })

  it('directions are unit vectors and radii are log-uniform within [r_min, r_max]', () => {
    const d = new Float64Array(3 * 512)
    const r = new Float64Array(512)
    patternInto(512, 7, 2, 300, d, r)
    for (let i = 0; i < 512; i++) {
      expect(Math.hypot(d[3 * i], d[3 * i + 1], d[3 * i + 2])).toBeCloseTo(1, 12)
      expect(r[i]).toBeGreaterThanOrEqual(2)
      expect(r[i]).toBeLessThanOrEqual(300)
    }
    // half the points inside the geometric mean radius (h1 = H2 is uniform)
    const gm = Math.sqrt(2 * 300)
    const inner = Array.from(r).filter((x) => x < gm).length
    expect(Math.abs(inner - 256)).toBeLessThanOrEqual(2)
    expect(PATTERN.maxPerAnchor).toBeGreaterThanOrEqual(512)
  })

  it('vehicle anchors: (r, observer elevation) of every point equal the server samples (j = 1)', () => {
    let n = 0
    for (const c of FIX.profiles) {
      // r of point 0 (h1 = 1/2) gives r_max: r0 = 2 sqrt(r_max / 2)
      const r0 = c.samples[0][0]
      const rMax = 2 * (r0 / 2) ** 2
      const dir = new Float64Array(3)
      c.samples.forEach(([r, e], i) => {
        const h1 = patternDir(i, 1, dir)
        expect(Math.abs(patternRadius(h1, 2, rMax) - r) / r).toBeLessThan(1e-9)
        expect(-Math.asin(dir[2]) * 180 / Math.PI).toBeCloseTo(e, 9)
        n++
      })
    }
    expect(n).toBe(8 * 256)
  })

  it('body anchors: world points equal the server samples (j = targetOrder * 4 + body, r_min 1, r_max = radius_max_m)', () => {
    const order = new Map<string, number>()
    for (const s of FIX.volumes.samples) if (!order.has(s.target)) order.set(s.target, order.size)
    const d = new Float64Array(3 * 256)
    const r = new Float64Array(256)
    for (const s of FIX.volumes.samples) {
      patternInto(256, order.get(s.target)! * 4 + s.body, 1, s.cfg.radius_max_m, d, r)
      s.points.forEach((p, i) => {
        for (let k = 0; k < 3; k++) expect(s.pos[k] + d[3 * i + k] * r[i]).toBeCloseTo(p[k] as number, 6)
      })
    }
  })
})
